'use strict';
const DEFAULT_SETTINGS={theme:'system',difficulty:'medium',bots:1,humans:1,memoryPairs:8,sound:true,volume:45,reducedMotion:false,comfortable:false,newTab:true,name:'Mitspieler',server:''};
let settings={...DEFAULT_SETTINGS,...saved('settings',{})};
const NETWORK_IDS=new Set(['chess','tictactoe','connect','mill','ludo','crazy8','memory','dice','draw','sound']);
// Eigene Netzwerk-Spiele werden explizit markiert.
GAMES.forEach(g=>{if(NETWORK_IDS.has(g.id)&&!g.mode.includes('network'))g.mode.push('network')});
function applySettings(){const root=document.documentElement;root.dataset.theme=settings.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):settings.theme;root.dataset.tone=['dark','midnight'].includes(root.dataset.theme)?'dark':'light';root.dataset.reduced=String(settings.reducedMotion);root.dataset.scale=settings.comfortable?'comfortable':'normal';persist('settings',settings);}
applySettings();matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if(settings.theme==='system')applySettings()});
const settingsNav=document.createElement('button');settingsNav.id='settings-open';settingsNav.className='nav-item';settingsNav.innerHTML='<span>⚙</span> Einstellungen';$('#nav-party').after(settingsNav);
const networkNav=document.createElement('button');networkNav.id='network-open';networkNav.className='nav-item';networkNav.innerHTML='<span>⌘</span> Netzwerk-Runde';settingsNav.before(networkNav);
const settingsDialog=document.createElement('dialog');settingsDialog.id='settings-dialog';settingsDialog.innerHTML='<div class="dialog-header"><h2>Einstellungen</h2><button class="close" aria-label="Einstellungen schließen">✕</button></div><div class="detail-tabs" role="tablist"><button class="active" role="tab" aria-selected="true" data-settingtab="appearance">Darstellung</button><button role="tab" aria-selected="false" data-settingtab="network">Mehrspieler</button></div><div id="settings-body"></div>';document.body.append(settingsDialog);
settingsDialog.querySelector('.close').onclick=()=>settingsDialog.close();settingsNav.onclick=()=>openSettings('appearance');
function openSettings(section='appearance'){settingsDialog.querySelectorAll('[data-settingtab]').forEach(b=>{const on=b.dataset.settingtab===section;b.classList.toggle('active',on);b.setAttribute('aria-selected',on);b.onclick=()=>openSettings(b.dataset.settingtab)});$('#settings-body').innerHTML=section==='appearance'?`<label class="field">Farbschema<select id="setting-theme"><option value="system">Wie mein Gerät</option><option value="light">Hell</option><option value="dark">Dunkel · Wald</option><option value="ocean">Ozean</option><option value="lavender">Lavendel</option><option value="sunset">Sonnenuntergang</option><option value="midnight">Mitternacht</option></select></label><label class="setting-check"><input type="checkbox" id="setting-sound" ${settings.sound?'checked':''}> Ton im Klanglabor aktivieren</label><label class="field">Lautstärke <span id="volume-label">${settings.volume}%</span><input type="range" id="setting-volume" min="0" max="100" value="${settings.volume}"></label><label class="setting-check"><input type="checkbox" id="setting-motion" ${settings.reducedMotion?'checked':''}> Animationen reduzieren</label><label class="setting-check"><input type="checkbox" id="setting-comfort" ${settings.comfortable?'checked':''}> Größere Schrift auf Spielkarten</label><label class="setting-check"><input type="checkbox" id="setting-tab" ${settings.newTab?'checked':''}> Anbieter in einem neuen Tab öffnen</label><p class="detail-note">Die Einstellungen werden in diesem Browser gespeichert. Der Ton-Regler betrifft die eigenen Spiele; externe Anbieter haben eigene Einstellungen.</p>`:`<label class="field">Dein Anzeigename<input id="setting-name" maxlength="24" value="${escapeHTML(settings.name)}"></label><label class="field">Spielraum-Server<input id="setting-server" type="url" placeholder="Leer = Server dieser Website" value="${escapeHTML(settings.server)}"></label><p class="dialog-description">Für das gleiche Netzwerk öffnet ihr alle die Netzwerkadresse des Rechners, auf dem Spielraum läuft. Dann bleibt dieses Feld leer. Ein öffentlich erreichbarer Server kann hier mit seiner HTTPS-Adresse eingetragen werden.</p><button id="server-check" class="secondary">Verbindung prüfen</button><p id="server-result" role="status"></p><details class="setup-guide"><summary>Wie starte ich eine LAN-Runde?</summary><ol><li>Projekt herunterladen und Node.js 20 oder neuer installieren.</li><li>Im Projektordner <code>npm start</code> starten, oder unter Windows <code>Start-Spielraum.cmd</code> öffnen.</li><li>Die angezeigte Netzwerkadresse auf allen Geräten öffnen. Alle Geräte müssen denselben Rechner erreichen können.</li><li>Beim Spiel „Mehrspieler“ wählen, Raum erstellen und den Einladungslink teilen.</li></ol><p>Der Rechner bleibt während der Runde eingeschaltet. Räume werden beim Server-Neustart gelöscht. Die Sites-Version stellt die Oberfläche bereit; für eigene Netzwerk-Räume benötigt sie einen erreichbaren Spielraum-Server.</p></details>`;
  if(section==='appearance'){
    $('#setting-theme').value=settings.theme;$('#setting-theme').onchange=e=>{settings.theme=e.target.value;applySettings()};
    for(const[id,key]of [['sound','sound'],['motion','reducedMotion'],['comfort','comfortable'],['tab','newTab']])$('#setting-'+id).onchange=e=>{settings[key]=e.target.checked;applySettings()};
    $('#setting-volume').oninput=e=>{settings.volume=+e.target.value;$('#volume-label').textContent=settings.volume+'%';applySettings()};
  }else{
    $('#setting-name').oninput=e=>{settings.name=e.target.value.trim().slice(0,24)||'Mitspieler';applySettings()};
    $('#setting-server').onchange=e=>{try{const value=e.target.value.trim();if(!value)settings.server='';else{const u=new URL(value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error();settings.server=u.origin;e.target.value=u.origin;}applySettings()}catch{e.target.value=settings.server;toast('Bitte eine gültige HTTP- oder HTTPS-Adresse ohne Zugangsdaten eingeben.')}};
    $('#server-check').onclick=async()=>{const result=$('#server-result');result.textContent='Verbindung wird geprüft …';try{await roomAPI('/api/health');result.textContent='Verbunden. Netzwerk-Räume sind bereit.';}catch(e){result.textContent=e.message;}};
  }
  showDialog('#settings-dialog');$('.sidebar').classList.remove('open');
}
const modeOption=document.createElement('option');modeOption.value='network';modeOption.textContent='Spielraum: LAN / Online';$('#mode').append(modeOption);
const categorySection=document.createElement('section');categorySection.className='category-section';categorySection.innerHTML='<div class="section-heading"><div><p class="eyebrow subtle">DEIN NÄCHSTES ABENTEUER</p><h2>Worauf hast du Lust?</h2></div><span>10 Spielwelten</span></div><div class="category-tiles"></div>';$('#library').before(categorySection);
categorySection.querySelector('.category-tiles').innerHTML=CATEGORIES.slice(1).map(c=>`<button class="category-tile" data-category="${c.id}"><img src="assets/category-${c.id}.svg" alt="" loading="lazy"><span><strong>${c.name}</strong><small>${GAMES.filter(g=>g.category===c.id).length} Spiele entdecken ↗</small></span></button>`).join('');
const originalRender=render;
render=function(){originalRender();document.querySelectorAll('[data-detail].card-art').forEach(el=>{const g=GAMES.find(g=>g.id===el.dataset.detail);if(g){const img=document.createElement('img');img.className='game-tile-image';img.src=`assets/category-${g.category}.svg`;img.alt='';img.loading='lazy';el.prepend(img);if(NETWORK_IDS.has(g.id))el.querySelector('.card-badge').textContent='● Direkt spielbar · ⌘ Netzwerk';}})};
details=function(id){const g=GAMES.find(g=>g.id===id);if(!g)return;$('#detail-content').innerHTML=`<div class="detail-art" style="--tile:${g.colors[0]};--tile-ink:${g.colors[1]}"><img src="assets/category-${g.category}.svg" alt=""><span aria-hidden="true">${g.symbol}</span></div><h2>${escapeHTML(g.name)}</h2><div class="detail-tabs" role="tablist" aria-label="Spielinformationen"><button role="tab" aria-selected="true" class="active" data-gametab="play">Spiel</button><button role="tab" aria-selected="false" data-gametab="manual">Handbuch</button><button role="tab" aria-selected="false" data-gametab="multiplayer">Mehrspieler</button></div><div id="detail-panel" role="tabpanel"></div>`;
  function panel(name){$('#detail-content').querySelectorAll('[data-gametab]').forEach(b=>{const on=b.dataset.gametab===name;b.classList.toggle('active',on);b.setAttribute('aria-selected',on)});$('#detail-panel').innerHTML=name==='manual'?handbookHTML(g):name==='multiplayer'?NETWORK_IDS.has(g.id)?`<p>Spielt auf getrennten Geräten im gleichen Netzwerk oder über euren öffentlich erreichbaren Spielraum-Server.</p><div class="detail-actions"><button class="primary" id="create-game-room">Raum erstellen ⌘</button><button class="secondary" id="join-game-room">Raum beitreten</button></div><button id="network-settings" class="text-button">Server & Verbindung einstellen ↗</button>`:`<p>${g.mode.includes('multi')?'Dieses Spiel nutzt die Online-Räume seines Anbieters. Erstellt dort einen privaten Tisch oder eine Lobby und teilt den dortigen Einladungslink.':g.engine&&g.mode.includes('couch')?'Dieses Spiel spielt ihr gemeinsam am selben Gerät. In Einstellungen → Spiele & Bots könnt ihr Computergegner hinzufügen.':'Dieses Spiel ist ein Solo-Spiel. Ihr könnt euch am selben Gerät abwechseln oder eure Ergebnisse vergleichen.'}</p>${g.url&&g.mode.includes('multi')?`<a class="primary" href="${g.url}" target="${settings.newTab?'_blank':'_self'}" rel="noopener noreferrer">Anbieter öffnen ↗</a>`:''}`:`<p>${escapeHTML(g.description)}</p><div class="detail-tags"><span>${g.players}</span><span>${g.time}</span>${g.mode.map(m=>`<span>${{solo:'Solo',multi:'Online beim Anbieter',couch:'Am selben Gerät',network:'LAN / eigener Online-Server'}[m]}</span>`).join('')}</div><div class="detail-note">${escapeHTML(g.note)}</div><div class="detail-actions">${g.engine?'<button class="primary" id="start-game">Jetzt spielen ▷</button>':`<a class="primary" href="${g.url}" target="${settings.newTab?'_blank':'_self'}" rel="noopener noreferrer">${['hiddenfolks','cardhunter'].includes(g.id)?'Anbieter ansehen':'Beim Anbieter starten'} ↗</a>`}<button class="secondary" id="add-party">${party.includes(g.id)?'Im Spieleabend ✓':'Zum Spieleabend +'}</button></div>`;
    if($('#start-game'))$('#start-game').onclick=()=>{$('#detail-dialog').close();startGame(g)};
    if($('#add-party'))$('#add-party').onclick=()=>{if(!party.includes(id)){party.push(id);persist('party',party)}$('#add-party').textContent='Im Spieleabend ✓';toast('Zum Spieleabend hinzugefügt')};
    if($('#create-game-room'))$('#create-game-room').onclick=()=>{$('#detail-dialog').close();openNetwork(g.id)};
    if($('#join-game-room'))$('#join-game-room').onclick=()=>{$('#detail-dialog').close();openNetwork(g.id,true)};
    if($('#network-settings'))$('#network-settings').onclick=()=>{$('#detail-dialog').close();openSettings('network')};
  }
  $('#detail-content').querySelectorAll('[data-gametab]').forEach(b=>b.onclick=()=>panel(b.dataset.gametab));panel('play');showDialog('#detail-dialog');
};
const originalStartGame=startGame;
startGame=function(g){originalStartGame(g);const tabs=document.createElement('div');tabs.className='detail-tabs';tabs.setAttribute('role','tablist');tabs.innerHTML='<button class="active" role="tab" aria-selected="true" data-playtab="game">Spiel</button><button role="tab" aria-selected="false" data-playtab="manual">Handbuch</button>';$('#play-content').before(tabs);const manual=document.createElement('div');manual.className='play-handbook';manual.hidden=true;manual.innerHTML=handbookHTML(g);$('#play-content').after(manual);tabs.querySelectorAll('button').forEach(b=>b.onclick=()=>{const isGame=b.dataset.playtab==='game';$('#play-content').hidden=!isGame;manual.hidden=isGame;tabs.querySelectorAll('button').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-selected',on)})});const previousCleanup=cleanup;cleanup=()=>{previousCleanup();tabs.remove();manual.remove();$('#play-content').hidden=false};};
$('#about-dialog').innerHTML='<div class="dialog-header"><h2>Open Source. Gemeinsam spielen.</h2><button class="close" aria-label="Schließen">✕</button></div><p>Spielraum bietet eigene Spiele und Links zu fremden Anbietern. Der eigene Projektcode, die Kurzhandbücher und die eigenen SVG-Kacheln stehen unter der MIT-Lizenz. Die Schach-Regelbibliothek chess.js verwendet BSD-2-Clause. Fremde Spiele und Marken behalten ihre eigenen Rechte.</p><p>Zehn eigene Spiele unterstützen getrennte Geräte über einen Spielraum-Server. Ein Rechner im lokalen Netzwerk kann den Server ohne zusätzliche Pakete starten. Mit öffentlichem HTTPS-Hosting funktioniert derselbe Server über das Internet.</p><p>Räume liegen im Arbeitsspeicher und enden beim Server-Neustart oder nach zwei Stunden ohne Aktivität. Anzeigenamen und Spielzüge werden nur an euren Spielraum-Server gesendet. Favoriten und Einstellungen bleiben im Browser.</p><p><a class="primary" href="https://github.com/xLordTime/Open-Browser-Game-Lib" target="_blank" rel="noopener noreferrer">Projekt auf GitHub ↗</a></p>';
$('#about-dialog .close').onclick=()=>$('#about-dialog').close();
$('#party-dialog .dialog-description').textContent='Sammle Spiele und kopiere die Einladung. Für eigene Netzwerk-Spiele erstellt ihr einen Spielraum; für externe Titel eine Lobby beim Anbieter.';
render();
